components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0 18px;
  border-radius: 2px;
  border: 2px solid var(--ink);
  background: var(--ink);
  color: var(--paper);
  box-shadow: 4px 4px 0 var(--stamp);
  font-family: var(--font-sans);
  font-weight: 800;
  font-size: 16px;
  letter-spacing: -0.03em;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.18s var(--ease), box-shadow 0.18s var(--ease), background-color 0.18s var(--ease), color 0.18s var(--ease);
}
.ds-btn-primary:hover {
  background: var(--ink);
  color: var(--paper);
  transform: translate(-2px, -2px);
  box-shadow: 7px 7px 0 var(--stamp);
}
.ds-btn-primary:focus-visible {
  outline: 3px solid var(--paper);
  outline-offset: 2px;
}
.ds-btn-primary:active {
  transform: translate(2px, 2px);
  box-shadow: 0 0 0 var(--ink);
}
.ds-btn-primary:disabled {
  background: var(--disabled);
  color: var(--paper);
  border-color: var(--disabled);
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
}

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0 18px;
  border-radius: 2px;
  border: 2px solid var(--ink);
  background: transparent;
  color: var(--ink);
  box-shadow: 4px 4px 0 var(--ink);
  font-family: var(--font-sans);
  font-weight: 800;
  font-size: 16px;
  letter-spacing: -0.03em;
  line-height: 1;
  cursor: pointer;
  transition: transform 0.18s var(--ease), box-shadow 0.18s var(--ease), background-color 0.18s var(--ease), color 0.18s var(--ease);
}
.ds-btn-secondary:hover {
  background: var(--ink);
  color: var(--paper);
  transform: translate(-2px, -2px);
}
.ds-btn-secondary:focus-visible {
  outline: 3px solid var(--paper);
  outline-offset: 2px;
}
.ds-btn-secondary:active {
  transform: translate(2px, 2px);
  box-shadow: 0 0 0 var(--ink);
}
.ds-btn-secondary:disabled {
  background: var(--disabled);
  color: var(--paper);
  border-color: var(--disabled);
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
}

.ds-field { display: flex; flex-direction: column; gap: 8px; width: 100%; }
.ds-label { font-family: var(--font-mono); font-weight: 500; font-size: 12px; line-height: 1.4; letter-spacing: 0.04em; color: var(--ink); }
.ds-input {
  width: 100%;
  min-height: 120px;
  background: var(--paper);
  color: var(--ink);
  border: 2px solid var(--ink);
  border-radius: 2px;
  padding: 12px 14px;
  box-shadow: 4px 4px 0 var(--ink);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
  outline: none;
  resize: vertical;
}
.ds-input::placeholder { color: #4a2c24; opacity: 1; }
.ds-input:focus { box-shadow: 4px 4px 0 var(--ink), 0 0 0 3px var(--paper), 0 0 0 6px var(--ink); }

.ds-chip {
  min-height: 44px;
  padding: 8px 12px;
  border-radius: 2px;
  border: 2px solid var(--ink);
  background: color-mix(in srgb, var(--paper) 35%, transparent);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.35;
  text-align: left;
  cursor: pointer;
}
.ds-chip:hover { background: var(--ember-row); }
.ds-chip:focus-visible {
  outline: 3px solid var(--paper);
  outline-offset: 2px;
  box-shadow: 0 0 0 6px var(--ink);
}

.ds-deck {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 72px;
  padding: 14px 16px;
  border: 2px solid var(--ink);
  border-radius: 2px;
  background: color-mix(in srgb, var(--paper) 28%, transparent);
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  font-family: var(--font-sans);
}
.ds-deck:hover { background: var(--ember-row); }
.ds-deck[aria-pressed="true"] { background: var(--paper); box-shadow: 4px 4px 0 var(--ink); }
.ds-deck[aria-pressed="true"]:hover { background: var(--paper); }
.ds-deck-copy { display: flex; flex-direction: column; gap: 2px; }
.ds-deck strong { font-weight: 800; letter-spacing: -0.03em; font-size: 16px; }
.ds-fine { font-size: 14px; line-height: 1.45; }
.ds-label { font-family: var(--font-mono); font-weight: 500; font-size: 12px; letter-spacing: 0.04em; line-height: 1.4; }
.ds-radio { width: 18px; height: 18px; border: 2px solid var(--ink); border-radius: 50%; flex: none; background: transparent; }
.ds-deck[aria-pressed="true"] .ds-radio { background: var(--ink); box-shadow: inset 0 0 0 3px var(--paper); }
.ds-deck:focus-visible { outline: 3px solid var(--paper); outline-offset: 2px; }

.ds-spread {
  width: 220px;
  min-height: 148px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 2px solid var(--ink);
  border-radius: 2px;
  background: color-mix(in srgb, var(--paper) 28%, transparent);
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  font-family: var(--font-sans);
}
.ds-spread:hover { background: var(--ember-row); }
.ds-spread[aria-pressed="true"] { background: var(--paper); box-shadow: 4px 4px 0 var(--ink); }
.ds-mark { width: 100%; height: 42px; }
.ds-spread strong { font-weight: 800; letter-spacing: -0.03em; font-size: 16px; }
.ds-fine { font-size: 14px; line-height: 1.45; }
.ds-label { font-family: var(--font-mono); font-weight: 500; font-size: 12px; letter-spacing: 0.04em; }
.ds-spread:focus-visible { outline: 3px solid var(--paper); outline-offset: 2px; }

.ds-card {
  --tilt: -7deg;
  width: 148px;
  aspect-ratio: 2 / 3;
  border: 2px solid var(--ink);
  background: var(--paper);
  box-shadow: 7px 7px 0 var(--ink);
  transform: rotate(var(--tilt));
  overflow: hidden;
  transition: transform 0.28s var(--ease), box-shadow 0.28s var(--ease);
}
.ds-card:hover {
  transform: rotate(calc(var(--tilt) - 1.5deg)) translateY(-7px);
  box-shadow: 11px 12px 0 var(--ink);
}
.ds-geo { display: block; width: 100%; height: 100%; }
@media (prefers-reduced-motion: reduce) {
  .ds-card, .ds-card:hover { transform: none; transition: none; }
}

.ds-mast {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 8px 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--ink);
  color: var(--ink);
}
.ds-wordmark {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  font-family: var(--font-sans);
  font-weight: 800;
  font-size: 22px;
  letter-spacing: -0.04em;
  line-height: 1;
  text-decoration: none;
  color: inherit;
}
.ds-sigil { width: 22px; height: 22px; display: block; transition: transform 0.45s var(--ease); }
.ds-wordmark:hover .ds-sigil, .ds-wordmark:focus-visible .ds-sigil { transform: rotate(18deg); }
.ds-mast-nav, .ds-tabbar { display: flex; }
.ds-mast-nav { gap: 4px 18px; }
.ds-mast-nav a, .ds-tabbar a {
  font-family: var(--font-mono);
  font-weight: 500;
  font-size: 12px;
  line-height: 1;
  letter-spacing: 0.04em;
  text-decoration: none;
  color: var(--ink);
}
.ds-mast-nav a { min-height: 44px; display: inline-flex; align-items: center; border-bottom: 2px solid transparent; }
.ds-mast-nav a:hover, .ds-mast-nav a[aria-current="page"] { border-bottom-color: var(--ink); }
.ds-tabbar {
  margin-top: 12px;
  background: var(--ember);
  border-top: 1px solid var(--ink);
  padding: 4px 6px;
}
.ds-tabbar a { flex: 1; min-height: 44px; display: flex; align-items: center; justify-content: center; }
.ds-tabbar a[aria-current="page"] { background: var(--ink); color: var(--paper); }
.ds-wordmark:focus-visible, .ds-mast-nav a:focus-visible, .ds-tabbar a:focus-visible {
  outline: 3px solid var(--paper);
  outline-offset: 2px;
  box-shadow: 0 0 0 6px var(--ink);
}

.ds-limit {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
  max-width: 440px;
  padding: 22px 20px;
  background: var(--ink);
  color: var(--paper);
  box-shadow: 8px 8px 0 var(--stamp);
}
.ds-limit-title {
  margin: 0;
  font-family: var(--font-sans);
  font-weight: 800;
  font-size: clamp(1.7rem, 4vw, 2.5rem);
  letter-spacing: -0.04em;
  line-height: 0.92;
  text-transform: uppercase;
  color: var(--paper);
}
.ds-limit p { margin: 0; color: var(--paper); font-family: var(--font-sans); font-size: 16px; line-height: 1.5; }
.ds-btn-on-ink {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0 18px;
  border-radius: 2px;
  border: 2px solid var(--ink);
  background: var(--paper);
  color: var(--ink);
  box-shadow: 4px 4px 0 var(--stamp);
  font-family: var(--font-sans);
  font-weight: 800;
  font-size: 16px;
  letter-spacing: -0.03em;
  line-height: 1;
  cursor: pointer;
  transition: transform 0.18s var(--ease), box-shadow 0.18s var(--ease), background-color 0.18s var(--ease);
}
.ds-btn-on-ink:hover { background: var(--ember); color: var(--ink); transform: translate(-2px, -2px); box-shadow: 7px 7px 0 var(--stamp); }
.ds-btn-on-ink:focus-visible { outline: 3px solid var(--paper); outline-offset: 2px; }
.ds-btn-on-ink:active { transform: translate(2px, 2px); box-shadow: 0 0 0 var(--ink); }

.ds-colophon {
  display: grid;
  gap: 8px;
  padding-top: 16px;
  border-top: 1px solid var(--ink);
  color: var(--ink);
  font-family: var(--font-mono);
  font-weight: 500;
  font-size: 12px;
  line-height: 1.45;
  letter-spacing: 0.03em;
}
.ds-colophon p { margin: 0; }
.ds-brand { display: flex; align-items: center; gap: 8px; }
.ds-brand .ds-sigil { width: 16px; height: 16px; }
.ds-colophon a { color: inherit; text-decoration: underline; text-underline-offset: 3px; }
@media (min-width: 800px) {
  .ds-colophon { grid-template-columns: 1.4fr 1fr auto; align-items: center; gap: 18px; }
  .ds-colophon p:nth-child(2) { text-align: center; }
  .ds-colophon p:nth-child(3) { text-align: right; }
}
